window.ROLES=[{"id": "gpahe", "url": "https://network-jobs.democracyfund.org/companies/global-project-against-hate-and-extremism/jobs/98159981-research-analyst", "lane": "osint", "fit": "green", "paytype": "fulltime", "where": "Remote", "short": true, "why": "Monitoring far-right movements with OSINT and turning it into reports and visuals is close to the research you already do on propaganda and influence operations.", "watch": "Asks for a BA; pay not listed. Posted Oct 27, 2026, so it is new.", "lane_label": "Disinformation & OSINT", "title": "Research Analyst", "org": "Global Project Against Hate and Extremism (GPAHE)", "location": "Remote; applicants in North America, Latin America, and Europe in compatible time zones will be considered", "remote_status": "Fully remote; occasional travel may be required for meetings or activities", "employment_type": "Not specified", "hours": "Not specified", "pay": "Salary/compensation commensurate with experience; no range provided. Comprehensive benefits package offered.", "deadline": "Not specified", "summary": "Research analysts monitor far-right extremist movements and trends across multiple issue areas and collect data that supports GPAHE publications and projects. The role develops and produces research and content for GPAHE’s advocacy efforts.", "duties": ["Monitor, collect, enter, and maintain data, ensuring data integrity.", "Use open-source information and techniques to collect data on far-right extremism.", "Apply creative and critical thinking to complex research questions.", "Research and write for ongoing projects on far-right extremism in countries covered by GPAHE.", "Communicate analysis of complex issues through articles, reports, PowerPoints, data visualizations, and/or other tools.", "Respond to correspondence and inquiries from external stakeholders.", "Work collaboratively with GPAHE staff.", "Perform other duties as assigned."], "required_qualifications": ["Demonstrated interpersonal communication skills.", "Demonstrated commitment to teamwork and collaboration.", "Ability to write clearly and concisely.", "Strong critical-thinking and problem-solving skills.", "Computer proficiency.", "Commitment to GPAHE’s mission, values, and advocacy.", "Commitment to equity, diversity, and inclusion."], "preferred_qualifications": ["Two years of experience preferred in researching, monitoring, analyzing, and writing on white supremacy and far-right extremism that undermines democracies and primarily impacts marginalized communities, and/or related topics.", "Demonstrated qualitative research experience.", "Proficiency in a non-English language highly preferred.", "Familiarity with data management and open-source investigation (OSINT) techniques preferred."], "education_requirement": "BA in journalism, sociology, political science, or a related field.", "how_to_apply": "Send a short note of interest and your resume to contact@globalextremism.org.", "archive": "", "urgent": "", "rank": 1, "headline": "Best mission and skills match. Remote, entry-to-mid level, posted Oct 27, 2026.", "reqs": [{"cat": "Required", "req": "Demonstrated interpersonal communication skills", "st": "have", "note": "15 years of B2B client work; \"Act as liaison\", \"Interview for info\" and \"Customer service\" are motivated skills."}, {"cat": "Required", "req": "Demonstrated commitment to teamwork and collaboration", "st": "have", "note": "Coordinated complex multi-party shipments and projects in sales; volunteer teams (immigration groups, courthouse watch)."}, {"cat": "Required", "req": "Ability to write clearly and concisely", "st": "have", "note": "Strong verbal and writing skills; public Steele guide and research digests show it."}, {"cat": "Required", "req": "Strong critical-thinking and problem-solving skills", "st": "have", "note": "Complex processing above average; evidence-first Russia influence-ops and Facebook attribution research."}, {"cat": "Required", "req": "Computer proficiency", "st": "have", "note": "Builds Obsidian knowledge bases, data visualizations and local AI research tools; \"Computer literate\" is a motivated skill."}, {"cat": "Required", "req": "Commitment to GPAHE’s mission, values, and advocacy", "st": "have", "note": "Has studied propaganda, tribalism and extremism since Trump’s first term; \"Help society\" is a top value."}, {"cat": "Required", "req": "Commitment to equity, diversity, and inclusion", "st": "have", "note": "Immigration volunteering; \"Diversity\" is a top value."}, {"cat": "Education", "req": "BA in journalism, sociology, political science, or related field", "st": "gap", "note": "Acquire: long-term (degree in progress, 15-20 credits, employer-reimbursed). Short-term: ask whether equivalent experience is accepted and lead with your portfolio."}, {"cat": "Preferred", "req": "2 years researching/writing on white supremacy and far-right extremism", "st": "gap", "note": "Partly have: years of self-directed, unpaid research. Acquire in 1-3 months: publish 2-3 short sourced pieces (e.g., Free State Project or NH far-right networks) as a portfolio."}, {"cat": "Preferred", "req": "Demonstrated qualitative research experience", "st": "have", "note": "Anthropology and sociology coursework; document and case analysis in your attribution projects."}, {"cat": "Preferred", "req": "Proficiency in a non-English language", "st": "gap", "note": "Acquire: long-term. Not a deal-breaker since it is \"preferred\"."}, {"cat": "Preferred", "req": "Familiarity with data management and OSINT techniques", "st": "have", "note": "OSINT webinars, Facebook case attribution, Obsidian evidence vault. Can strengthen in weeks: Trace Labs event or a free OSINT course."}], "loc": "remote", "paylabel": "Pay not listed", "saved": "saved/gpahe.pdf"}, {"id": "newsguard", "url": "https://www.newsguardtech.com/careers/staff-reporter-analyst/", "lane": "journalism", "fit": "green", "paytype": "fulltime", "where": "Remote considered (NYC preferred)", "short": true, "why": "You would trace who owns and funds anonymous sites and write plain-language debunks. It is entry-level and the job includes mentoring.", "watch": "Pay tops out at $70K. They want a strictly apolitical voice, and the process includes a writing test.", "lane_label": "Explanatory journalism & fact-checking", "title": "Staff Reporter", "org": "NewsGuard", "location": "New York, NY (25 W. 52nd Street, 15th Floor, New York, NY 10019)", "remote_status": "The ability to work from New York is strongly preferred; strong remote candidates will be considered.", "employment_type": "Full Time", "hours": "", "pay": "US-based staff: $52,000–$70,000 per year, depending on experience.", "deadline": "Applications are reviewed and interviews are held on a rolling basis.", "summary": "NewsGuard analysts produce detailed ratings of news and information sites and report on TV news programs, networks, streaming news channels, and podcasts. They also write in-depth reports on trends and issues in online misinformation.", "duties": ["Produce detailed ratings for news and information sites, assessing each site’s trustworthiness based on nine apolitical, journalistic criteria.", "Track down funding and ownership for anonymous websites that spread falsehoods.", "Debunk inaccuracies.", "Preemptively warn users about dubious sources before they are widely shared.", "Assess TV news programs and networks, streaming news channels, and podcasts.", "Write in-depth, high-profile reports about key trends and issues in online misinformation."], "required_qualifications": ["Have college journalism experience or one to two years of industry or other relevant professional experience.", "Have excellent writing, reporting, and fact-checking skills with a strong eye for detail.", "Write simply and succinctly, avoiding jargon or flowery language.", "Have experience navigating social media platforms and apps for online disinformation.", "Consume and engage with news in various formats, ranging from podcasts and streaming services to the digital versions of “legacy” news outlets.", "Be curious, thorough, and persistent, with the ability to ferret out information, such as a publication’s ownership or financial backing, through reporting and research.", "Approach the role in a determinedly apolitical, non-ideological manner.", "Be eager to work for a fast-paced, ambitious journalism organization obsessed with quality and where the product and processes are continually evolving.", "Be eager to be mentored and have their careers advanced by some of the most accomplished journalists in the business.", "Be committed to NewsGuard’s mission and vision."], "preferred_qualifications": [], "education_requirement": "College journalism experience, or one to two years of industry or other relevant professional experience.", "how_to_apply": "Submit a current resume/CV with professional work experiences, three references, and optionally a cover letter through NewsGuard’s application form. Candidates must be available for interviews with NewsGuard staff members and able to take a writing test.", "archive": "https://web.archive.org/web/20261102142528/https://www.newsguardtech.com/careers/staff-reporter-analyst/", "urgent": "", "rank": 2, "headline": "Entry-level disinformation analyst with mentoring. Remote considered; pay is $52-70K.", "reqs": [{"cat": "Required", "req": "College journalism experience or 1-2 years of industry or other relevant professional experience", "st": "gap", "note": "Partly have: years of self-directed misinformation research, but none of it paid or published by an outlet. Acquire in 1-3 months: 2-3 published fact-checks or source ratings (Substack, local outlet, Granite State Progress fellowship)."}, {"cat": "Required", "req": "Excellent writing, reporting, and fact-checking skills with a strong eye for detail", "st": "have", "note": "Strong writing and editing; \"Proofread/edit\" is a motivated skill; source-quality grading in the Steele guide."}, {"cat": "Required", "req": "Write simply and succinctly, avoiding jargon", "st": "have", "note": "You like to make things digestible with analogies and visuals."}, {"cat": "Required", "req": "Experience navigating social media platforms and apps for online disinformation", "st": "have", "note": "Facebook campaign attribution; disinformation digest across Global/US/NH."}, {"cat": "Required", "req": "Consume news in many formats (podcasts, streaming, digital legacy outlets)", "st": "have", "note": "Daily digest habit and multi-source research."}, {"cat": "Required", "req": "Ferret out information such as a publication’s ownership or financial backing", "st": "have", "note": "Russia influence-ops records research and campaign attribution are exactly this."}, {"cat": "Required", "req": "Approach the role in a determinedly apolitical, non-ideological manner", "st": "gap", "note": "Watch item. Your values drive your work, and NewsGuard rates sources across the spectrum. Acquire now: choose a writing sample on rating a source’s practices, not its politics."}, {"cat": "Required", "req": "Eager for a fast-paced, evolving journalism organization", "st": "gap", "note": "I do my best work with focused, self-paced research. Mitigate: ask about rating-cycle pacing and workflow in the interview."}, {"cat": "Required", "req": "Eager to be mentored", "st": "have", "note": "\"Knowledge\" is your top value; you love learning and iteration."}, {"cat": "Required", "req": "Committed to NewsGuard’s mission", "st": "have", "note": "Long-standing focus on misinformation and inoculation theory."}, {"cat": "Process", "req": "Writing test and three references", "st": "gap", "note": "Acquire in weeks: practice a timed source rating using NewsGuard’s nine public criteria; line up three references (managers, volunteer leads)."}], "loc": "remote", "paylabel": "$52-70K"}, {"id": "massbudget", "url": "https://massbudget.org/2026/09/01/job-opening-housing-and-human-services-policy-analyst/", "lane": "policy", "fit": "yellow", "paytype": "fulltime", "where": "Remote-first (MA or commutable; NH ok)", "short": true, "why": "Budget and tax policy for low-income families, turned into fact sheets and infographics. The pay meets your $70K floor and the role is remote-first.", "watch": "Wants 1-3 years of policy analysis, strong Excel and public speaking. The priority deadline has passed, though it is still open until filled.", "lane_label": "Policy research & data storytelling", "title": "Housing and Human Services Policy Analyst", "org": "MassBudget", "location": "Must reside in Massachusetts or within a reasonable commuting distance from Massachusetts.", "remote_status": "Remote-first; staff may be required to attend in-person meetings and events as needed.", "employment_type": "Full time", "hours": "35-hour work week", "pay": "$79,673–$89,764, based on qualifications and experience. MassBudget does not negotiate salary.", "deadline": "Open until filled. Priority deadline was September 20, 2026, at 11:59 p.m.; applications received by then were prioritized for review.", "summary": "The Policy Analyst will research and analyze policy across Massachusetts, with a primary focus on housing and a secondary focus on human services programs, including food security and transitional aid. The role also involves advocacy, partnership work, public education, and communicating research findings to diverse audiences. The employee will be required to register as a lobbyist in Massachusetts.", "duties": ["Conduct policy research and create accessible written reports and fact sheets on housing and human services policy, including policies related to affordable housing and access to affordable, healthy food.", "Disaggregate data by race, ethnicity, and income to convey accurate and compelling analyses about housing and human services policy.", "Work with MassBudget’s Communications team to create accessible content, such as infographics, videos, social media content, and other materials supporting research findings.", "Coordinate with the Advocacy Director to collaborate with coalitions and partners to advance policies addressing housing and human services in Massachusetts.", "Coordinate with the Deputy Director of Research and Policy Analysis to track and analyze state investments in housing and human services.", "Develop the organization’s annual goals and plans with other Research staff; explore best practices and policy ideas; and occasionally fact check peer research.", "Collaborate with national, state, and local partners to exchange information on best practices, and attend conferences and other meetings of interest to MassBudget.", "Speak on housing and human services policy matters to the general public, advocacy groups, legislators, and the press; equip diverse stakeholders with MassBudget’s research findings, data analysis, and policy recommendations.", "Lead MassBudget’s research and outreach on state budget proposals for housing and human services policy areas, and provide related state budget and tax information to partners and policymakers.", "Work with MassBudget’s development team on donor engagement and reporting on the organization’s housing and human services policy work.", "Conduct presentations and training sessions about the state budget process for external audiences across Massachusetts, as needed.", "Support the Deputy Director of Research and Policy Analysis in developing accessible and relevant state budget education materials."], "required_qualifications": ["Minimum of 1–3 years of dedicated economic or policy analysis experience, preferably in housing policy or other issues related to human services policy and improving the lives of individuals and families with low and middle incomes.", "Strong technical skills in Microsoft Excel, specifically when used to analyze large datasets.", "Commitment to building racial and economic equity in alignment with MassBudget’s mission.", "Detail-oriented collaborator with proven experience managing projects and deadlines effectively.", "Very strong written and oral communication skills."], "preferred_qualifications": ["Understanding of state policymaking.", "Proficiency with statistical and/or data visualization software, such as R, Stata, and Tableau.", "Knowledge of a second language that is prevalent in Massachusetts.", "Experience with—and enthusiasm for—public speaking."], "education_requirement": "", "how_to_apply": "Email a resume and cover letter to jobs@massbudget.org. Use “LAST NAME, FIRST NAME, Applicant for Housing and Human Services Policy Analyst” as the email subject line.", "archive": "https://web.archive.org/web/20261102142837/https://massbudget.org/2026/09/01/job-opening-housing-and-human-services-policy-analyst/", "urgent": "", "rank": 4, "headline": "Meets your $70K+ goal and is remote-first, but the requirements are a reach. The priority deadline has passed.", "reqs": [{"cat": "Required", "req": "1-3 years of dedicated economic or policy analysis experience", "st": "gap", "note": "Partly have: self-directed NH tax and education-funding analysis using ACS microdata. Acquire in 3-12 months: a fellowship (GSP, NHFPI intern) plus published briefs."}, {"cat": "Required", "req": "Strong Microsoft Excel skills for analyzing large datasets", "st": "gap", "note": "Acquire in 1-3 months: data analytics course (pivot tables, Power Query, XLOOKUP) via tuition reimbursement. Note: numbers-heavy work is on your burnout list."}, {"cat": "Required", "req": "Commitment to racial and economic equity", "st": "have", "note": "Core values: poverty, wealth inequality, tax fairness."}, {"cat": "Required", "req": "Detail-oriented collaborator managing projects and deadlines", "st": "have", "note": "15 years shipping millions of dollars a year in complex hardware orders."}, {"cat": "Required", "req": "Very strong written and oral communication", "st": "have", "note": "Strong verbal and writing skills; 15 years of client communication in sales."}, {"cat": "Preferred", "req": "Understanding of state policymaking", "st": "have", "note": "NH policy analysis project, courthouse watch, local government interest."}, {"cat": "Preferred", "req": "Proficiency with R, Stata, or Tableau", "st": "gap", "note": "Acquire in 2-4 months: Tableau Public portfolio piece (e.g., your NH tax profiles) or an intro R course."}, {"cat": "Preferred", "req": "A second language common in Massachusetts", "st": "gap", "note": "Acquire: long-term; preferred only."}, {"cat": "Preferred", "req": "Experience with and enthusiasm for public speaking", "st": "gap", "note": "Mixed: you enjoy briefing your own findings but not performing. Acquire in weeks: one recorded 10-minute briefing on your NH research."}, {"cat": "Condition", "req": "Must register as a Massachusetts lobbyist; live in MA or within commuting distance", "st": "have", "note": "NH within commuting distance qualifies; registration is paperwork."}], "loc": "remote", "paylabel": "$79.7-89.8K"}, {"id": "gsp", "url": "https://granitestateprogress.org/about/join-our-team/", "lane": "civic", "fit": "green", "paytype": "parttime", "where": "Concord NH office, some hours from home", "short": true, "why": "This NH fellowship covers the Free State Project and ALEC: tracking votes, following the money and checking tips. At 10+ hours a week you can keep your current job.", "watch": "Paid only when funding allows. Mostly office-based in Concord.", "lane_label": "Civic tech & democracy", "title": "Research Fellow", "org": "Granite State Progress", "location": "Concord, New Hampshire", "remote_status": "Based out of the Concord office; a limited number of hours may be completed at home.", "employment_type": "Internship / fellowship; may be for class credit, paid, or unpaid. Paid internships are offered when possible, but paid positions are not always available.", "hours": "At least 10+ hours per week on a regular schedule; more hours are available.", "pay": "Paid when possible; unpaid internships may also be available.", "deadline": "", "summary": "The Research Fellow monitors elected officials, candidates, and political groups for opportunities for accountability, and conducts research on issues, policy stances, voting records, campaign donations, and other information as needed. Granite State Progress provides ongoing training and social networking opportunities.", "duties": ["Monitor and identify hot-button political issues at the local, state and federal level.", "Assist partner organizations in research requests on specific issues or elected officials.", "Track legislative issues and whip counts on priority bills.", "Track voting records and statements of election officials and candidates.", "Contribute to Free State Project Watch and ALEC Exposed research efforts and reports.", "Investigate tips from the public, particularly concerning financial records and ethics issues."], "required_qualifications": ["Committed to progressive issues and ideals.", "Creative and willing to push the envelope with hard-hitting communications activities.", "Excellent at verbal and written communication.", "Organized and detail-oriented.", "Brave enough to suggest their own ideas for campaigns and tactics.", "Able to take charge of independent projects but willing to come together as a team for big campaign pushes.", "Must enjoy/pretend to enjoy mandatory (office) family fun days and social networking events."], "preferred_qualifications": ["Ideal candidate: “Your fifth-grade book report read like a thesis; you dream of breaking the stories that will land on national media.”"], "education_requirement": "", "how_to_apply": "Send a letter of interest and resume to info@granitestateprogress.org. Note which fellowship position you are most interested in and whether you are applying for class credit, a paid internship, or an unpaid internship.", "archive": "https://web.archive.org/web/20261024085205/https://granitestateprogress.org/about/join-our-team/", "urgent": "", "rank": 3, "headline": "Best foot-in-the-door option. NH-based fellowship, 10+ hrs/week, so you can keep your current job.", "reqs": [{"cat": "Required", "req": "Committed to progressive issues and ideals", "st": "have", "note": "Your values: poverty, inequality, tax policy, education funding, climate."}, {"cat": "Required", "req": "Creative and willing to push the envelope with hard-hitting communications", "st": "have", "note": "\"Creative expression\" and \"Initiate change\" are top values and skills; you make infographics and visual explainers."}, {"cat": "Required", "req": "Excellent verbal and written communication", "st": "have", "note": "Strong verbal and writing skills."}, {"cat": "Required", "req": "Organized and detail-oriented", "st": "have", "note": "15 years of order logistics and hardware specs; \"Plan/organize\" is a motivated skill."}, {"cat": "Required", "req": "Brave enough to suggest own ideas for campaigns and tactics", "st": "have", "note": "\"Innovate\", \"Initiate change\" and \"Make decisions\" are motivated skills."}, {"cat": "Required", "req": "Can run independent projects and join team pushes", "st": "have", "note": "Self-directed research practice; team selling."}, {"cat": "Required", "req": "Enjoy (or pretend to enjoy) office fun days and networking events", "st": "gap", "note": "Low priority for you (entertain/perform). Acquire: none needed; a few events a year."}, {"cat": "Duties", "req": "Track bills, whip counts, voting records; Free State Project Watch; ALEC Exposed", "st": "have", "note": "NH policy analysis project (tax profiles, education/Medicaid) and courthouse-watch volunteering."}, {"cat": "Duties", "req": "Investigate public tips on financial records and ethics issues", "st": "have", "note": "Records-based attribution research; OSINT training."}, {"cat": "Practical", "req": "Work mostly from the Concord office, with some hours from home", "st": "gap", "note": "Acquire: ask for a schedule such as 1-2 office days plus remote research hours."}], "loc": "local", "paylabel": "Paid when possible"}, {"id": "owid", "url": "https://ourworldindata.org/hiring-writer-2026", "lane": "journalism", "fit": "yellow", "paytype": "fulltime", "where": "Remote (some UK-hours overlap)", "short": true, "why": "Data-driven explainers on poverty, inequality and health, built with visualizations. It matches your goal of making complex material digestible.", "watch": "Stretch goal. You must already have three published, single-authored data articles from before Apr 1, 2026. Treat it as a portfolio target.", "lane_label": "Explanatory journalism & fact-checking", "title": "Writer", "org": "Our World in Data", "location": "Oxford, United Kingdom; international applicants welcome", "remote_status": "Remote work is possible; many team members work remotely. Applicants should partly overlap with core UK working hours. Visa sponsorship may be considered depending on individual circumstances and relocation preference.", "employment_type": "Full-time preferred; part-time may be considered for the right candidate. Contract.", "hours": "Flexible hours within a full-time load; some overlap with core UK working hours is expected, with allowances possible for exceptional candidates.", "pay": "£80,000 to £120,000 per year, based on experience and location.", "deadline": "No fixed deadline; applications remain open until an offer is made and are reviewed in monthly batches.", "summary": "Our World in Data is seeking an experienced writer who regularly publishes single-authored, data- and research-based writing for a general audience and can cover a broad range of global issues. The writer will work closely with Deputy Editor Hannah Ritchie, collaborate with data scientists on visualizations, and first complete a paid writing residency producing two articles.", "duties": ["Write clear, engaging, and insightful articles on topics such as health, poverty and inequality, technological change, demographics, or human rights, making important data and research findings on the world’s largest problems accessible to a large, non-specialist audience.", "Collaborate closely with data scientists to produce relevant data and interactive visualizations presenting evidence on the topics you are writing about.", "In a more senior editorial position, work with the editorial team to identify and prioritize topics to cover, setting the agenda for topics and ensuring they are impactful and aligned with the mission.", "Participate in the editorial process by providing constructive feedback on colleagues’ drafts.", "Engage in strategic discussions about the data and research to cover, the development of the website and tools, and how the organization engages with users."], "required_qualifications": ["A track record of clear, engaging, and informative public writing for a general audience—pieces conceived, researched, and written independently—that rely on well-chosen data and build on the relevant research literature.", "High agency: already thinks and writes frequently about topics relevant to Our World in Data.", "Good understanding of statistics and excellent ability to interpret and engage critically with data from different sources.", "Comfort selecting the right data and framing for visualizations, and coming up with designs that make articles clearer and more compelling.", "Interest and ability to write across a broad range of topics.", "Strong editorial judgment: knowing which questions are worth asking, which data is worth using, and how to frame things for a general audience.", "Strong interest in global issues and commitment to the values and mission of Our World in Data.", "Ability to analyze information critically and change your mind based on evidence.", "Openness to editorial feedback and an iterative writing process.", "High sense of agency, initiative, and ability to work independently on projects from conception to completion.", "Curiosity and desire to learn in-depth about a diverse range of topics.", "Drive to present information in engaging and creative ways.", "Ability to understand and consider diverse perspectives, particularly when discussing sensitive or complex global issues."], "preferred_qualifications": ["Experience creating visualizations; this could be taught."], "education_requirement": "", "how_to_apply": "Submit an application through the Google Form. It asks for a CV; links to three relevant articles published in English before April 1, 2026, and no more than five years old; a Data Insight on an indicator provided in the form (title maximum 100 characters and text maximum 850 characters); and links to social media profiles used to share public writing, if any. Accepted articles include pieces published on Substack, Medium, a personal blog, or traditional media. Long social-media notes or threads, academic articles or commentaries, theses or dissertations, and more than one co-authored article are not accepted. The organization expects a high volume of applications and will contact only candidates invited to the next round. Questions: jobs@ourworldindata.org; use the subject line “Writer position 2026”.", "archive": "https://web.archive.org/web/20260910140213/https://ourworldindata.org/hiring-writer-2026", "urgent": "", "rank": 5, "headline": "Stretch, north-star role. A great fit for the work you love, but it needs a published portfolio first.", "reqs": [{"cat": "Required", "req": "Track record of independent, data-based public writing for a general audience (3 articles published before Apr 1, 2026)", "st": "gap", "note": "Hard gap for this cycle unless you already have three qualifying pieces. Acquire in 3-6 months for the next opening: publish 3 single-authored data articles on Substack or Medium."}, {"cat": "Required", "req": "Already thinks and writes frequently about OWID topics", "st": "have", "note": "Poverty, inequality, public health, energy and climate are your core values."}, {"cat": "Required", "req": "Good understanding of statistics; critical engagement with data from many sources", "st": "gap", "note": "Partly have: data analytics coursework and ACS microdata work. Acquire in 1 semester: an intro statistics course (reimbursable)."}, {"cat": "Required", "req": "Choose the right data and framing for visualizations", "st": "have", "note": "Data viz explorers, infographics, phone-friendly research viewers."}, {"cat": "Required", "req": "Write across a broad range of topics", "st": "have", "note": "Wide research range, from disinformation to policy to energy."}, {"cat": "Required", "req": "Strong editorial judgment", "st": "have", "note": "Source-quality grading in the Steele guide; research-question design notes."}, {"cat": "Required", "req": "Analyze critically and change your mind based on evidence", "st": "have", "note": "You study motivated reasoning and inoculation theory and apply them to your own work."}, {"cat": "Required", "req": "Open to editorial feedback and iterative writing", "st": "have", "note": "You prefer work that is reviewed and iterated."}, {"cat": "Required", "req": "Work independently from conception to completion", "st": "have", "note": "Completed multiple self-directed projects; note that task initiation is a developmental area, so structure helps."}, {"cat": "Process", "req": "Data Insight sample (850 characters) and paid writing residency", "st": "have", "note": "Your short-form digests are close to this format."}, {"cat": "Practical", "req": "Partly overlap with core UK working hours", "st": "have", "note": "Eastern Time mornings overlap with UK afternoons."}], "loc": "remote", "paylabel": "£80-120K"}, {"id": "isd", "url": "https://www.isdglobal.org/wp-content/uploads/2026/05/ISD-Threat-Analyst.pdf", "lane": "osint", "fit": "yellow", "paytype": "fulltime", "where": "US remote or hybrid", "why": "Extremism monitoring, social listening and briefings for NGOs and policymakers, at $55-90K.", "watch": "May 2026 PDF. The ISD careers page lists no open roles, so confirm before applying. Includes out-of-hours incident work.", "lane_label": "Disinformation & OSINT", "title": "Threat Analyst", "org": "Institute for Strategic Dialogue-US (ISD-US)", "location": "US", "remote_status": "Hybrid or Remote", "employment_type": "Full time, permanent", "hours": "", "pay": "$55,000-$90,000 + benefits", "deadline": "", "summary": "The Threat Analyst researches online radicalization, terrorist use of the internet, and the relationship between online rhetoric and offline violence and other illegal activity. The role uses quantitative and qualitative digital research to identify credible, specific, or imminent threats and produces analysis and briefings for internal and external stakeholders.", "duties": ["Conduct qualitative and quantitative analysis, through digital ethnography and tools (e.g. Pyrra, Brandwatch) to detect online activity with the potential to impact threats to public safety, development of new tactics to influence real-world threats, and activities by groups and movements that pose threats to public safety.", "Analyze the impact of real-world events and developments, such as global conflicts or incidents of political violence, on public safety in the United States.", "Produce clear and concise analytical products based on threat investigations.", "Lead quality control efforts for outputs, including written reports, alerts, and PowerPoint decks for verbal briefings.", "Author and review or edit clear, data-driven, and accessible analysis for stakeholders and audiences such as law enforcement, policymakers, NGOs, and the broader public.", "Review and copyedit collaborative products.", "Produce and/or support written briefs, alerts, PowerPoints, and other products.", "Contribute to managing the team-wide project management tracker.", "Collect, process, and analyze reporting related to potential extremist and terrorist activity in North America.", "Produce quick-turn intelligence alerts and other products on real-world plots and attacks that include relevant takeaways and insights for the reader.", "Manage data, including cleanup, file storage, and retention."], "required_qualifications": ["Subject matter expertise on extremist or terrorist groups, subcultures of nihilistic violence, hacktivist groups, or violent online networks.", "Proficiency with social listening tools.", "Experience and knowledge of online analytical tools and approaches, including but not limited to social media analysis, network mapping, or OSINT techniques.", "Experience producing and tailoring briefs for varying audiences, such as law enforcement and NGOs.", "Exceptional written and spoken English.", "Outstanding attention to detail.", "Highly organized, with the ability to be flexible, multitask, and respond proactively in a fast-paced environment.", "Ability to work well both independently and in a team.", "Ability to be flexible with working hours as needed for out-of-hours incidents and events."], "preferred_qualifications": ["Master’s degree qualification or relevant work experience in a relevant field.", "Multi-stakeholder engagement experience.", "Background and understanding of information manipulation tactics, hostile foreign state actors, and/or cyberhacktivist activities.", "2+ years professional experience as a researcher or analyst.", "Professional experience in law enforcement, media, government, or another field requiring the ability to quickly digest data and produce or tailor written products for varying audiences.", "Editing skills.", "Graphic design and/or data visualization skills, such as Tableau or Google Data Studio.", "Public speaking experience.", "Foreign language skills, particularly Mandarin, Spanish, Russian, Farsi, or Arabic."], "education_requirement": "A Master’s degree qualification or relevant work experience in a relevant field is listed as desirable.", "how_to_apply": "", "archive": "https://web.archive.org/web/20260506183136/https://www.isdglobal.org/wp-content/uploads/2026/05/ISD-Threat-Analyst.pdf", "urgent": "", "short": false, "loc": "remote", "paylabel": "$55-90K"}, {"id": "apart", "url": "https://apartresearch.com/careers/ai-cyber-threat-researcher-osint", "lane": "tns", "fit": "yellow", "paytype": "freelance", "where": "Remote", "urgent": "Nov 3, 2026", "why": "Part-time contract OSINT on AI misuse at $80-120/hr. Combines your AI, cyber and OSINT interests.", "watch": "Closes Nov 3 (end of day, Anywhere on Earth). Wants hands-on CTI/OSINT and web-infrastructure skills (HTTP, DNS).", "lane_label": "Trust & safety / threat intel", "title": "AI Cyber Threat Researcher (OSINT)", "org": "Apart Research", "location": "Remote (4+ hours overlap with CET working hours preferred)", "remote_status": "Fully remote", "employment_type": "Full-time or part-time contracting", "hours": "", "pay": "$80–$120/h, adjusted depending on location, seniority, and experience; it can be higher for exceptional candidates or specific locations with higher costs of living.", "deadline": "3 November 2026, end of day (Anywhere on Earth)", "summary": "The researcher will discover and triage real-world incidents involving AI agents and AI-enabled misuse, documenting evidence and passing promising cases to the research team and forensic partners. Findings will inform research on AI manipulation and misuse and contribute to a shared incident dataset for the safety and policy community.", "duties": ["Hunt for incidents across the open internet, monitoring public sources such as URL scanning and sandbox services, web archives, public relays and proxies, code repositories, forums, social media, and dark-web channels for signs of AI agent activity or AI-enabled misuse.", "Develop sensors for rogue agent traffic by designing and deploying honeypots, canary tokens, and decoy web services, and building detection rules that distinguish agent traffic from ordinary bots and human users.", "Pivot on indicators such as distinctive payloads, user agents, encoded command strings, or account-creation patterns to search at scale and map the full extent of activity.", "Track evolving tactics by maintaining indicator sets and conducting meta-analysis to keep up with changing tools and techniques.", "Triage and document candidate incidents by assessing credibility, severity, and research value, preserving evidence carefully, and writing clear incident summaries.", "Package cases for researchers and forensic partners, and stay involved as investigations proceed.", "Contribute to attribution, including distinguishing fully autonomous agents from human-directed or human-assisted activity.", "Build repeatable, partially automated workflows from manual hunting, using LLMs and scripting wherever helpful."], "required_qualifications": ["Hands-on experience in OSINT, cyber threat intelligence, threat hunting, or trust & safety investigations.", "Strong ability to pivot on indicators and connect weak signals across disparate public sources.", "Solid technical literacy: comfort with web infrastructure (HTTP, DNS, URLs, encodings), log and dataset analysis, and scripting (Python or similar).", "Rigour in evidence handling and the ability to write clear, well-sourced reports for both technical and policy audiences.", "Comfort working fast and independently in an ambiguous, new problem area."], "preferred_qualifications": ["Experience tracking threat actor TTPs using frameworks such as MITRE ATT&CK.", "Familiarity with LLM agents, tool use, and how agents interact with web services.", "Background in influence operations, disinformation, or coordinated inauthentic behaviour research.", "Experience in government, intelligence, or a threat intelligence vendor.", "Interest in AI safety and how evidence shapes AI policy."], "education_requirement": "", "how_to_apply": "Apply for this role. Questions about the role or how applicant data is processed: careers@apartresearch.com.", "archive": "https://web.archive.org/web/20261028171814/https://apartresearch.com/careers/ai-cyber-threat-researcher-osint", "short": false, "loc": "remote", "paylabel": "$80-120/hr"}, {"id": "welo", "url": "https://www.indexventures.com/startup-jobs/remote/fact-checking-analyst-english-us/", "lane": "journalism", "fit": "green", "paytype": "freelance", "where": "Remote", "why": "A 2-week freelance fact-checking project at $45/hr. Low risk, and it adds a paid verification credit to your resume.", "watch": "Short-term AI-training work. Watch for repetitive tasks done to a fixed guideline.", "lane_label": "Explanatory journalism & fact-checking", "title": "Fact Checking Analyst - English (US)", "org": "Welo Data", "location": "USA", "remote_status": "Remote", "employment_type": "Freelance", "hours": "", "pay": "$45/hr (US)", "deadline": "", "summary": "Fact Checking Analysts evaluate the accuracy of information and claims against available evidence, using research, analytical thinking, and sound judgment. The work includes particular attention to local and location-based information and contributes to improving the accuracy, reliability, and trustworthiness of AI-generated information.", "duties": ["Review information and identify claims requiring verification.", "Research and validate claims using reliable online sources and available evidence.", "Assess source credibility, relevance, consistency, and timeliness when determining claim accuracy.", "Analyse conflicting information and determine the most reasonable conclusion based on available evidence.", "Distinguish between verified facts, assumptions, opinions, and unverifiable information.", "Apply critical thinking and judgment when evaluating claims that require deeper investigation.", "Evaluate information within its relevant context and consider factors that may impact accuracy.", "Document findings clearly and assign appropriate accuracy ratings according to project guidelines.", "Maintain high levels of quality, consistency, and attention to detail while completing assigned tasks.", "Determine the most authoritative source when multiple sources provide conflicting information and clearly justify evidence-based decisions."], "required_qualifications": ["Educational background or equivalent experience in Journalism, Research, Editorial, Communications, Content Analysis, Public Policy, Law, Information Scientist, or a related field.", "Strong written English comprehension and communication skills.", "Strong online research and information verification skills.", "Excellent analytical thinking, reasoning, and attention to detail.", "Comfortable making evidence-based decisions when information is incomplete, ambiguous, or contradictory.", "Ability to work independently and consistently apply detailed project guidelines.", "Proficiency with web research tools, search engines, and online information sources.", "Strong documentation skills and the ability to clearly explain findings and decision rationale."], "preferred_qualifications": [], "education_requirement": "Educational background or equivalent experience in Journalism, Research, Editorial, Communications, Content Analysis, Public Policy, Law, Information Scientist, or a related field.", "how_to_apply": "Apply by answering a few quick questions to join Welo Data’s database and contributor community.", "archive": "", "urgent": "", "short": false, "loc": "remote", "paylabel": "$45/hr", "saved": "saved/welo.pdf"}, {"id": "ballotpedia", "url": "https://careers.uw.edu/jobs/ballotpedia-local-expansion-staff-researcher-remote/", "lane": "civic", "fit": "yellow", "paytype": "fulltime", "where": "100% remote", "urgent": "Nov 5, 2026", "why": "Remote election research summarizing local candidates and ballot measures. Fully remote with no degree listed.", "watch": "$42.5-44K plus an $8K stipend, below your target. Much of the work is repetitive data entry against guidelines.", "lane_label": "Civic tech & democracy", "title": "Local Expansion Staff Researcher (Remote)", "org": "Ballotpedia", "location": "Remote; work from home. Specific location requirements are not stated.", "remote_status": "100% remote", "employment_type": "Full-time", "hours": "Not specified; flexible scheduling", "pay": "Starting pay range: $42,500–$44,000 per year, commensurate with experience. Annual benefits stipend of $8,000, paid in equal increments each paycheck once benefits-eligible.", "deadline": "November 5, 2026", "summary": "Ballotpedia is seeking a full-time, 100% remote Local Expansion Staff Researcher. Reporting to the Local Expansion Managing Editor, the researcher will gather official election documents and information for local elections, enter data into Ballotpedia’s database, support candidate research workflows, and monitor election calendars.", "duties": ["Research reliable election information sources and conduct outreach to gather official election documents for local contests.", "Process and ingest election and candidate data into Ballotpedia’s database, using automated tools and manual review.", "Monitor changes to election schedules and documentation to ensure Ballotpedia reflects up-to-date information for upcoming local elections.", "Maintain and improve databases of sources and research processes to enhance the consistency and completeness of election coverage.", "Review data for accuracy and completeness, making corrections based on Ballotpedia’s data standards and current database information.", "Build knowledge of state and local election practices across assigned jurisdictions to support accurate interpretation of election materials.", "Research election laws and other relevant electoral topics as needed.", "Identify opportunities and implement workflows to add depth and quality to Ballotpedia’s local election coverage.", "Improve access to Ballotpedia’s local election coverage on-site and promote that coverage."], "required_qualifications": ["Passion for elections, election and voter information, and politics, with commitment to Ballotpedia’s mission of providing neutral, fact-based, objective coverage.", "Excellent research skills and ability to follow general guidelines to locate appropriate online and direct outreach sources and record information in an organized, concise manner.", "Resourcefulness, curiosity, and ability to investigate information that falls outside existing processes and communicate findings.", "Exceptional attention to detail and ability to understand complex processes and consistently follow instructions across many iterations.", "Ability to accurately and concisely summarize complex concepts, difficult text, and detailed structures.", "Sharp critical-thinking skills and ability to understand varied source structures and apply general categories and logical statements.", "Ability to work collaboratively, proactively communicate progress, share relevant discoveries, and coordinate shared research.", "Interest in organizing information through clear structures.", "Willingness to receive and implement critical feedback for continuous improvement.", "Proficiency with Google Chrome, Docs, and Sheets, or similar tools, to find, record, organize, and clean up information gathered from the Internet.", "Interest in or experience using AI tools to increase productivity.", "A computer with Internet access."], "preferred_qualifications": [], "education_requirement": "Not specified.", "how_to_apply": "Visit the Ballotpedia job opportunities page and fill out the form. Attach a résumé and a cover letter detailing your interest in Ballotpedia’s mission and this position, both in PDF format. Ensure that either the résumé or cover letter includes your current address.", "archive": "", "short": false, "loc": "remote", "paylabel": "$42.5-44K + $8K stipend", "saved": "saved/ballotpedia.pdf"}, {"id": "adl", "url": "https://careers-adl.icims.com/jobs/2919/analyst,-center-on-extremism/job", "lane": "osint", "fit": "yellow", "paytype": "fulltime", "where": "Hybrid 3 days/wk (any ADL office)", "why": "Extremism research with OSINT and social media monitoring, at $71-75K.", "watch": "Three office days a week (ADL has a Boston office), which conflicts with your no-daily-Boston limit.", "lane_label": "Disinformation & OSINT", "title": "Analyst, Center on Extremism", "org": "ADL", "location": "Anywhere ADL has an office; New York City preferred (CSC). Locations listed: New York, NY, and US.", "remote_status": "Hybrid; this role requires 3 days in person.", "employment_type": "Regular Full-Time", "hours": "Additional hours may be needed on occasion to keep up with heavy workload and attend special events.", "pay": "$71,000–$75,000. Actual salary is commensurate with experience and reflects the budget for the position; ADL has a location-based compensation structure, so the range may differ for candidates in other locations.", "deadline": "", "summary": "The Analyst researches and analyzes antisemitism across ideological movements and demographics, producing public reports and articles as well as internal analyses. The role also contributes to agency responses to research findings and delivers presentations and trainings to law enforcement and other constituents.", "duties": ["Research and analyze antisemitic movements and ideologies, groups, and individuals.", "Develop qualitative and quantitative analysis of the subject area using a range of technical tools.", "Write and edit internal memoranda based on research findings for agency use.", "Create written reports and articles, and deliver verbal presentations and trainings to external partners, law enforcement, and other outside constituents.", "Collaborate in the planning and execution of agency responses to research findings.", "Serve as a resource to regional offices and CSC departments on relevant subject matter by providing information, guidance, and other assistance.", "Ensure that research materials and findings are properly archived for use by current and future ADL employees."], "required_qualifications": ["Well versed in contemporary and historical antisemitism.", "Excellent research skills in primary and secondary sources.", "Demonstrated experience with social media monitoring tools and OSINT techniques.", "Interest in and ability to quickly learn new technologies and adapt to a changing research environment.", "Ability to switch between quantitative and qualitative analytic lenses.", "Ability to thrive in a demanding, fast-paced, multitasking environment.", "Excellent analytical and writing skills.", "Ability to demonstrate good judgment, especially when under pressure.", "Committed to contributing to a culture where everyone thrives.", "Collaborative team player.", "Creative and innovative; takes initiative.", "Results-oriented; a problem solver rather than a problem identifier.", "Excels in dynamic environments that require adaptability.", "Ability to manage multiple priorities simultaneously.", "Energized by ADL’s mission and work.", "The ideal candidate has several years of demonstrable experience and expertise in research, academia, or public policy."], "preferred_qualifications": ["Graduate degree preferred."], "education_requirement": "Bachelor’s degree or equivalent experience required.", "how_to_apply": "Apply online using the “Apply for this job online” option.", "archive": "https://web.archive.org/web/20260729003910/https://careers-adl.icims.com/jobs/2919/analyst%2c-center-on-extremism/job", "urgent": "", "short": false, "loc": "hybrid", "paylabel": "$71-75K"}, {"id": "graphika", "url": "https://www.graphika.com/careers/senior-research-analyst-influence-operations", "lane": "osint", "fit": "red", "paytype": "fulltime", "where": "NY hybrid / Remote US", "why": "Influence-operations analysis: the exact field of your Russia research.", "watch": "Senior role (3+ years of TI/OSINT). Status is unclear. Use it as a model of where this path leads.", "lane_label": "Disinformation & OSINT", "title": "Senior Research Analyst, Influence Operations", "org": "Graphika", "location": "New York, NY", "remote_status": "Hybrid (listed in the header); Remote (US/EU) (stated in the description)", "employment_type": "Full-time", "hours": "", "pay": "", "deadline": "", "summary": "Graphika is seeking an experienced network analyst to lead investigations into coordinated inauthentic behavior and state-linked influence operations. The analyst will work with platform and enterprise clients to produce structured intelligence reports.", "duties": ["Lead investigations into coordinated inauthentic behavior and state-linked influence operations.", "Work closely with platform and enterprise clients to produce structured intelligence reports."], "required_qualifications": ["3+ years in threat intelligence or OSINT.", "Experience with network graph analysis.", "Strong written communication."], "preferred_qualifications": [], "education_requirement": "", "how_to_apply": "Apply through the job listing. For questions before applying, email careers@graphika.com.", "archive": "", "urgent": "", "short": false, "loc": "remote", "paylabel": "Pay not listed", "saved": "saved/graphika.pdf"}, {"id": "midas", "url": "https://www.themidasproject.com/careers/senior-investigator", "lane": "tns", "fit": "red", "paytype": "fulltime", "where": "Remote", "why": "Investigating AI-company accountability. A strong mission match.", "watch": "Senior pay ($148-174K) and senior investigative experience required. Aspirational.", "lane_label": "Trust & safety / threat intel", "title": "Senior Investigator", "org": "The Midas Project", "location": "Remote", "remote_status": "Remote", "employment_type": "Full-time", "hours": "Flexible hours; no specific weekly hours stated", "pay": "$148,500–$173,500, commensurate with experience", "deadline": "Applications reviewed on a rolling basis; apply as soon as possible", "summary": "You'll run the investigations driving the organization's work and write them up for Model Republic, its publication covering the AI industry, policy, and the forces shaping the rules of AI. You'll help shine a light on conflicts of interest, influence campaigns, and emerging risks as the world begins to confront highly powerful AI systems, then turn that evidence into rigorous, readable stories that journalists, policymakers, and the public can rely on.", "duties": ["Conduct independent investigations into AI companies, including their governance, safety practices, lobbying, and political influence.", "Research and write in-depth Model Republic articles, from quick-turn analysis to major investigative pieces.", "Synthesize information from diverse sources such as corporate disclosures, legal filings, regulatory documents, campaign finance records, social media, and tips.", "Compare companies' published commitments against their actual behavior, including compliance with safety frameworks and laws such as California's AI safety rules.", "Offer editing and fact-checking support to investigations from others on the team or freelancers writing for Model Republic."], "required_qualifications": [], "preferred_qualifications": ["Experience in investigative journalism, policy research, corporate accountability campaigns, or similar research-intensive fields.", "A portfolio of published work showing clear, compelling, and precise writing.", "Demonstrated ability to find and verify information through internet research.", "Strong analytical skills and the ability to synthesize large amounts of information.", "Familiarity with major AI companies, technology risks, policy debates, and safety issues, or the ability to develop expertise quickly.", "Strong attention to detail.", "Bonus: OSINT or data skills, such as scraping, social media analysis, SQL, or Python.", "Bonus: Existing relationships with reporters covering AI."], "education_requirement": "", "how_to_apply": "The posting encourages interested applicants to apply as soon as possible. It does not specify an application method in the provided text.", "archive": "https://web.archive.org/web/20261007184745/https://www.themidasproject.com/careers/senior-investigator", "urgent": "", "short": false, "loc": "remote", "paylabel": "$148.5-173.5K"}, {"id": "action", "url": "https://www.idealist.org/en/consultant-job/e84220caff94433da5d2df952480c8f9-research-analyst-action-research-kings-county", "lane": "policy", "fit": "red", "paytype": "fulltime", "where": "Remote US", "why": "Child welfare research at $61-75K, fully remote.", "watch": "Requires a BA plus 4 years, and the work is heavy on statistics in SPSS or R (numbers are on your burnout list).", "lane_label": "Policy research & data storytelling", "title": "Research Analyst", "org": "Action Research", "location": "Remote; work can be performed from anywhere in the United States. Associated location: 318 5th St, Suite 300, Brooklyn, NY 11215.", "remote_status": "Remote", "employment_type": "Full Time", "hours": "", "pay": "USD $61,000–$75,000 per year, depending on skills and level of experience. The posting describes this as a best estimate rather than a firm or final offer.", "deadline": "Applications accepted until the position is filled; applications reviewed on a rolling basis.", "summary": "The Research Analyst will analyze administrative data and help assess child welfare system performance across multiple jurisdictions, primarily supporting reforms arising from federal class action litigation and settlement agreements. The role includes data cleaning, analysis, validation, quality assurance, and communicating findings to technical and nontechnical audiences. Action Research is a small, collaborative, fully remote team working with court monitoring teams in Kansas, Michigan, New Mexico, and Texas.", "duties": ["Clean, organize, and document administrative data; identify and resolve errors, inconsistencies, duplicates, missing values, and formatting issues; and assess data completeness, reliability, and suitability for analysis.", "Write and execute reproducible, well-documented syntax or code to analyze large and complex administrative datasets accurately and efficiently.", "Replicate and independently validate performance calculations submitted by public agencies.", "Review data, code, calculations, tables, written findings, and colleagues’ analytic work for accuracy, consistency, and clarity.", "Interpret analytic results and translate them into clear technical memos, internal materials, public reports, presentations, and other products for technical and nontechnical audiences.", "Present and discuss analytic findings with colleagues, court monitoring teams, government agencies, and other partners.", "Track developments in state and local reform efforts and prepare background materials for meetings with state and monitoring teams.", "Maintain workplans and documentation, coordinate project activities, and communicate proactively about progress, risks, and competing priorities.", "As needed, support interviews, focus groups, case reviews, desk research, and literature reviews, and synthesize key insights for project teams and partners.", "Help project teams connect analytic findings to emerging questions, decisions, and next steps.", "Share analytic approaches, documentation, strategies, and lessons with colleagues to strengthen practice across the organization."], "required_qualifications": ["Bachelor’s degree and at least four years of relevant professional experience, or master’s degree and at least two years of relevant professional experience. Relevant fields may include public policy, data science, economics, sociology, public health, public administration, and social work.", "Professional or academic experience contributing to applied research, program evaluation, performance measurement, administrative data analysis, public policy analysis, or closely related work.", "Demonstrated experience cleaning and analyzing complex datasets using SPSS, R, or comparable statistical software (e.g., Stata, SAS, Python), including writing reproducible syntax or code.", "Strong quantitative reasoning, including the ability to interpret results, investigate unexpected findings, recognize data quality concerns, and explain the implications and limitations of an analysis.", "Experience producing accurate, well-documented work and conducting careful quality assurance reviews.", "Ability to manage multiple assignments effectively and efficiently, both independently and collaboratively, while meeting deadlines and communicating proactively.", "Excellent written and oral communication skills, including the ability to convey methods, findings, limitations, and implications clearly to technical and nontechnical audiences.", "Strong interpersonal skills and the ability to establish constructive working relationships with colleagues and external partners.", "Proficiency in Microsoft Office, particularly Excel and PowerPoint, and comfort using online collaboration and project management tools such as Box, Slack, and AirTable.", "Willingness and ability to travel to New York City at least once per year and limited travel to other project jurisdictions as needed; Action Research covers business travel expenses."], "preferred_qualifications": ["Knowledge of child welfare systems, policies, data, or practice.", "Experience analyzing child welfare, human services, education, or other public-sector administrative data.", "Experience using analysis to inform service delivery, program improvement, system reform, or policy decision-making.", "Experience with performance measurement, data validation, or independent verification of reported metrics.", "Experience conducting qualitative or mixed-methods research, including interviews, focus groups, case reviews, or literature reviews.", "Experience working with government agencies, nonprofit organizations, courts, or other public-sector partners.", "Spanish or other language fluency."], "education_requirement": "Bachelor’s degree and at least four years of relevant professional experience, or a master’s degree and at least two years of relevant professional experience. Relevant fields may include public policy, data science, economics, sociology, public health, public administration, and social work.", "how_to_apply": "Submit a resume, responses to three questions, and a short writing sample. Questions: (1) Why are you interested in this position and in Action Research’s work? (2) Describe your experience with analyzing administrative data or large-scale quantitative analysis, including the statistical software you have used. (3) What is something not on your resume that you think makes you a strong fit for this role? The writing sample should demonstrate the ability to communicate research, analytics, or policy findings clearly, be primarily your own work, and explain your role in producing any coauthored material. Applications are reviewed on a rolling basis and accepted until the position is filled. The organization is unable to respond to individual phone or email inquiries about application status.", "archive": "https://web.archive.org/web/20260928223353/https://www.idealist.org/en/consultant-job/e84220caff94433da5d2df952480c8f9-research-analyst-action-research-kings-county", "urgent": "", "short": false, "loc": "remote", "paylabel": "$61-75K"}, {"id": "recidiviz", "url": "https://techjobsforgood.com/jobs/36715/", "lane": "civic", "fit": "yellow", "paytype": "fulltime", "where": "Remote US", "why": "Entry-level civic data analyst for criminal-justice reform at $85K. No degree listed.", "watch": "Needs SQL with window functions and Python/Pandas, plus 6 months of data experience. Doable in 6-12 months with your analytics courses.", "lane_label": "Civic tech & democracy", "title": "Data Analyst (Entry-Level)", "org": "Recidiviz", "location": "Remote (US), New York City, or Oakland, CA", "remote_status": "Remote in the United States; also available in New York City or Oakland, CA", "employment_type": "Full-time", "hours": "", "pay": "$85,000 per year", "deadline": "", "summary": "The Data Analyst will work with criminal justice data and teammates across Recidiviz to develop analyses and insights that target the drivers of incarceration. The role includes carrying out well-defined analyses, building visualizations, preparing data for product launches, and communicating findings to internal teams and state partners.", "duties": ["Explore datasets to find patterns and insights about American criminal justice systems.", "Carry out well-scoped analyses with guidance from senior analysts and the State Engagement team.", "Support product launches in the states where Recidiviz works by following established launch processes, preparing the analytical data each launch needs, and flagging data discrepancies.", "Build clear, well-documented visualizations and dashboards using existing tools.", "Communicate findings to internal teams, and present to state partners alongside teammates.", "Analyze trends in areas related to Recidiviz’s work to understand how its products function."], "required_qualifications": ["Strong communication and collaboration skills, to help nurture a knowledgeable, data-oriented culture.", "Enthusiasm for working with internal and external partners from diverse backgrounds and worldviews, such as government staff, researchers, journalists, technical staff, and practitioners in criminal justice reform.", "Care and curiosity in inspecting source data and checking results closely, so the data and analyses you prepare can be trusted and reused.", "6 or more months of practical experience exploring, analyzing, and cleaning real-world datasets. Internships and research count, and part-time roles count when their hours add up to roughly 6 months of full-time work.", "Working proficiency in SQL, including joins, aggregations, and window functions.", "Familiarity with Python, specifically the Pandas package, for data analysis and visualization."], "preferred_qualifications": ["Interest in criminal justice or public policy, or experience working with public-sector data.", "Experience with a BI or dashboarding tool such as Looker or Tableau.", "Familiarity with any part of Recidiviz’s data stack, which includes Google Cloud Platform, BigQuery, Looker, Jupyter notebooks, and Python/Pandas."], "education_requirement": "", "how_to_apply": "", "archive": "https://web.archive.org/web/20261020230625/https://techjobsforgood.com/jobs/36715/", "urgent": "", "short": false, "loc": "remote", "paylabel": "$85K"}, {"id": "njpp", "url": "https://jobs.deel.com/new-jersey-policy-perspective/job-details/da7ae620-ab95-4d24-a77b-6b6de53a76c2/overview", "lane": "policy", "fit": "red", "paytype": "fulltime", "where": "New Jersey-based, hybrid", "why": "Tax and budget policy analyst ($85-90K). Shows what a tax-policy role asks for.", "watch": "Must live in NJ. Kept here as a model for the NH equivalents (NHFPI) when they post.", "lane_label": "Policy research & data storytelling", "title": "Tax and Budget Policy Analyst", "org": "New Jersey Policy Perspective (NJPP)", "location": "Trenton, NJ, United States; based in New Jersey, with travel to Trenton, Newark, and other locations across the state as needed", "remote_status": "Hybrid; in-person meetings as needed, with flexibility for remote work", "employment_type": "Full-time", "hours": "", "pay": "$85,000–$90,000 USD, based on experience; benefits include health care, retirement, and generous vacation leave, sick leave, and holiday schedules.", "deadline": "Open until filled", "summary": "NJPP seeks a Policy Analyst to lead research and analysis on New Jersey’s tax system and state budget, explaining their effects on residents, low- and moderate-income households, racial equity, and state government effectiveness. The analyst will produce accessible research and recommendations, represent NJPP in policy and coalition spaces, and help ensure community perspectives inform budget proposals.", "duties": ["Conduct in-depth research, data analysis, and policy monitoring on tax and budget policy issues aligned with NJPP’s priorities, and synthesize findings into actionable policy recommendations.", "Draft reports, explainers, blog posts, op-eds, and fact sheets that translate complex research into accessible, actionable content for diverse audiences.", "Identify new, emerging issues in tax and budget policies that affect state residents, with particular focus on benefiting low-to-middle-income residents, communities of color, and other historically excluded groups.", "Monitor and shape policy developments in your issue area(s), including legislation, state budgets, and administrative actions.", "Represent NJPP at legislative hearings, coalition meetings, and public forums, articulating NJPP’s research and recommendations to policymakers, funders, and stakeholders.", "Engage with media, partners, and the public as an expert in your issue area(s), providing clear and compelling analysis.", "Cultivate and maintain strong working relationships with directly impacted communities, coalition partners, and policymakers.", "Collaborate with communications staff on messaging, visuals, and video content, as well as press materials, report rollouts, public statements, and media outreach related to your policy issues.", "Collaborate with fellow analysts to review and strengthen NJPP publications through peer reviews and fact checking, as needed.", "Assist the development team with grant reporting and foundation meetings related to your policy portfolio, as needed.", "Provide support for onboarding and mentoring of interns, as needed.", "Travel within New Jersey for hearings, meetings, and events, and remain flexible to take on related duties as organizational needs evolve."], "required_qualifications": ["Strong qualitative and quantitative data analysis skills and ability to quickly absorb and analyze potential changes in tax policy and government spending.", "Ability to analyze complex data and translate findings into actionable insights.", "Facility with Excel and other data analysis tools.", "Excellent writing and speaking skills, with a track record of producing clear, compelling materials for non-technical audiences.", "Strong demonstrated ability to translate technical legal or policy changes into real-world terms and impacts for people with limited technical expertise.", "Strong editorial judgment and commitment to accuracy.", "Demonstrated commitment to racial, economic, and social justice through an intersectional lens.", "Strong relationship-building skills with communities, coalitions, policymakers, and funders.", "Experience working constructively in a team environment.", "Strong project management skills, with the ability to balance multiple priorities and meet deadlines.", "Creative problem-solving skills and the ability to anticipate opportunities or challenges.", "Ability to receive feedback and adapt work product to respond to feedback.", "Flexibility to adapt as organizational needs and policy landscapes evolve."], "preferred_qualifications": ["Minimum of 1–3 years of experience in policy research, analysis, or advocacy, or equivalent professional experience.", "Familiarity with New Jersey’s state budget and legislative processes.", "Subject-matter expertise in tax policy or government budgeting.", "Experience with testimony to government bodies and educational meetings with lawmakers and policymakers.", "Experience with public speaking and press interviews on technical topics."], "education_requirement": "A bachelor’s degree (master’s preferred) in public policy, economics, sociology, or a related field, or equivalent professional experience.", "how_to_apply": "Submit a resume, a cover letter highlighting relevant experience and skills, and 1–3 writing samples featuring relevant research or demonstrating the ability to analyze complex issues and present findings clearly for a broad audience. For accommodation requests or application issues, email careers@njpp.org.", "archive": "", "urgent": "", "short": false, "loc": "hybrid", "paylabel": "$85-90K", "saved": "saved/njpp.pdf"}, {"id": "blueRose", "url": "https://job-boards.greenhouse.io/blueroseresearch/jobs/6238808004", "lane": "bridge", "fit": "yellow", "paytype": "fulltime", "where": "Remote (DC preferred)", "why": "Turns polling research into clear materials for political staff, at $65-75K.", "watch": "Wants 1-3 years in Democratic politics and plenty of coordination work.", "lane_label": "Bridge roles (use your sales/logistics years)", "title": "Communications and Political Associate", "org": "Blue Rose Research", "location": "Washington, DC", "remote_status": "Remote work is listed; Washington, D.C., is strongly preferred but not required.", "employment_type": "", "hours": "", "pay": "$65,000–$75,000 annually, depending on experience.", "deadline": "", "summary": "An early-career role focused on drafting, research, and coordination, with guidance and review from senior staff. The associate will turn research into clear, useful materials for political leaders, clients, and the press.", "duties": ["Draft and edit memos, presentations, and other client-facing materials, bringing together research findings and relevant background.", "Draft talking points, Q&A documents, and briefing materials for press appearances, with leadership review; keep past materials organized for reuse.", "Monitor news and media coverage to identify opportunities for timely polling and message testing.", "Prepare research summaries and background materials for Blue Rose staff ahead of briefings with Democratic campaigns, elected officials, advocacy organizations, and other political partners.", "Collect and organize talking points, public statements, and social media content for message testing."], "required_qualifications": ["Typically 1–3 years of experience in Democratic politics, campaigns, legislative offices, or progressive advocacy; internship experience counts.", "Strong writing and editing skills, including the ability to turn research into clear, accurate talking points, memos, and briefing materials.", "Comfort coordinating meetings and materials with political staff, clients, and media contacts, with guidance from senior staff.", "Working knowledge of Democratic politics, key organizations, and the current news landscape.", "Strong organization and attention to detail, with the ability to manage schedules, drafts, and requests under tight deadlines.", "Good judgment about when to take initiative, ask questions, and flag a problem, and willingness to revise work based on feedback.", "Commitment to helping Democrats win and using research to inform political decisions.", "Must be authorized to work lawfully in the United States."], "preferred_qualifications": ["Experience with polling, message testing, or political research; a quantitative or research background is welcome but not required.", "Experience with media training or interview preparation.", "Based in Washington, D.C."], "education_requirement": "", "how_to_apply": "Apply through the job application page. The form requests a resume or other application document (PDF, DOC, DOCX, TXT, or RTF) and includes required written responses: an answer of up to 250 words about Democrats’ biggest communications challenge and advice for addressing it, and an email of up to 300 words summarizing linked research for an official side office of the applicant’s choosing. LinkedIn and website fields are optional. Applicants based in D.C. are asked whether they can attend in-person meetings and briefings in Washington, D.C., 2–3 days per week.", "archive": "", "urgent": "", "short": false, "loc": "remote", "paylabel": "$65-75K", "saved": "saved/blueRose.pdf"}, {"id": "checkmyads", "url": "https://checkmyads.org/were-hiring/", "lane": "bridge", "fit": "yellow", "paytype": "fulltime", "where": "Remote US (ET hours)", "why": "Ad-tech accountability nonprofit at $90-105K. Uses your 15 years of B2B relationship skills on a mission you care about.", "watch": "It is fundraising and partnership sales, and selling is on your low-priority list. Requires a BA.", "lane_label": "Bridge roles (use your sales/logistics years)", "title": "Strategic Partnerships Manager", "org": "Check My Ads Institute", "location": "United States (US-based applicants only)", "remote_status": "Fully remote; must be able to work Eastern Time (ET) hours.", "employment_type": "Full-time", "hours": "40 hours/week", "pay": "$90,000–$105,000 USD/year; offers commensurate with experience.", "deadline": "", "summary": "Check My Ads Institute is seeking a results-oriented Strategic Partnerships Manager with experience in fundraising and/or revenue-focused marketing to expand sustainable funding through donor relationships and strategic partnerships. The role leads donor outreach and cultivation, develops corporate and brand partnerships, and stewards external civil society relationships in collaboration with the Programs team. It is remote for US-based applicants and includes travel as needed.", "duties": ["Design and implement a comprehensive fundraising strategy in partnership with the Programs team.", "Align fundraising goals with programmatic priorities, impact metrics, and revenue targets.", "Track performance against goals, analyze results, and refine strategies to optimize revenue.", "Research and scope out new potential donors—including foundations, individual major donors, and corporate donors.", "Help identify new institutional funding opportunities and collaborate closely with the program and administrative teams to develop, draft, and submit grant applications.", "Help maintain a robust donor pipeline, ensuring consistent follow-up and engagement.", "Identify funding opportunities through brands and corporate sponsorship initiatives.", "Write personal, compelling, and authentic letters and emails to individual donors and prospects; maintain a regular cadence of donor touchpoints and support stewardship activities including thank-yous, impact updates, and renewal outreach.", "Research and pitch brand-aligned corporate funding opportunities; support the development of sponsorship packages and partnership decks.", "Manage donor information and activity tracking in Pipedrive, ensuring accurate data entry and reporting, and continuously improve CRM processes.", "Prepare and deliver updates and communications to external civil society partnerships; maintain relationships with external partners, attend coalition calls, liaise, and share ongoing updates.", "Develop external partner- and funder-facing explainers and other materials, in partnership with the Programs team."], "required_qualifications": ["Bachelor degree is required.", "Demonstrated experience in fundraising, development, strategic partnerships, or revenue-focused marketing.", "Proven ability to build, cultivate, and steward donor and partner relationships.", "Experience developing and executing fundraising or revenue strategies aligned with organizational goals.", "Strong written communication skills, with the ability to craft compelling and personalized donor outreach.", "Demonstrated experience identifying, pitching, and managing corporate or brand partnerships.", "Ability to collaborate cross-functionally in a remote, mission-driven environment.", "Willingness and ability to travel as needed to represent the organization.", "Must be US-based and able to work Eastern Time (ET) hours."], "preferred_qualifications": [], "education_requirement": "Bachelor degree required.", "how_to_apply": "Apply through the application form on the posting. The form accepts PDF, DOC, and DOCX files up to 20 MB, and PDFs up to 5 MB (maximum 3 files). Applicants are asked: “Share an example of how you built, cultivated and stewarded a donor or partner relationship over time. Specify the context of the relationship, your ways of engagement and the outcome of your stewardship efforts.”", "archive": "https://web.archive.org/web/20250903164443/https://checkmyads.org/were-hiring/", "urgent": "", "short": false, "loc": "remote", "paylabel": "$90-105K"}, {"id": "crew", "url": "https://www.idealist.org/en/nonprofit-job/66ca112a788047fe82fc7c6d0ed65ea1-fact-checker-citizens-for-responsibility-and-ethics-in-washington-washington", "lane": "journalism", "fit": "red", "paytype": "fulltime", "where": "DC on-site", "why": "Ethics-watchdog fact-checker. CREW also posts spring research internships.", "watch": "On-site in DC and requires a BA.", "lane_label": "Explanatory journalism & fact-checking", "title": "Fact-Checker", "org": "Citizens for Responsibility and Ethics in Washington (CREW)", "location": "Washington, DC, USA", "remote_status": "On-site; hybrid work options potentially available", "employment_type": "Full Time", "hours": "", "pay": "USD $52,000–$65,000 per year, based on experience and qualifications", "deadline": "", "summary": "CREW seeks an analytical, meticulous fact-checker to review its written work and support research into corruption and democracy issues. Reporting to the VP of Research, the role also includes vetting prospective interns, hires, and collaborators for potential risks, conflicts, or liabilities. The position is part of a union-represented collective bargaining unit.", "duties": ["Conduct comprehensive reviews of CREW written content, including investigations, graphics, reports, and legal filings, for accuracy, thoroughness, and sourcing by analyzing text, recreating analyses, and working with project leads on areas of concern.", "Conduct targeted deep dives into niche research areas or potential hires and produce documents detailing findings.", "Exhaustively uncover and investigate corruption and democracy issues to assist with CREW projects, including reviewing and analyzing government documents, news reports, databases, and other resources.", "Vet new interns, hires, and other collaborators to spot any risks, conflict, or liability they might pose."], "required_qualifications": ["Bachelor’s degree required.", "1+ years of work experience.", "Commitment to accuracy and rigorous attention to detail.", "Outstanding research and analytical skills.", "Good instincts about news sources and credibility.", "Persistence and resourcefulness in tracking down information.", "Excellent written and oral communication skills.", "Ability to work both as part of a team and independently.", "A deep, demonstrated interest in searching through public documents and other sources to find obscure information.", "Must remain organized in a fast-paced environment, adapt to changing situations, and prioritize numerous projects and tasks."], "preferred_qualifications": ["Work experience, including internships, preferably in a nonprofit, government, campaign, or comparable setting."], "education_requirement": "Bachelor’s degree required.", "how_to_apply": "Email a resume and cover letter to jobs@citizensforethics.org. Include your last name and “Fact-Checker” in the subject line. No phone calls. CREW is only able to respond to candidates it contacts for an interview.", "archive": "", "urgent": "", "short": false, "loc": "hybrid", "paylabel": "$52-65K", "saved": "saved/crew.pdf"}, {"id": "flashpoint", "url": "https://jobs.greycroft.com/companies/flashpoint/jobs/88189953-senior-analyst-i-trust-safety", "lane": "tns", "fit": "red", "paytype": "fulltime", "where": "Remote US", "why": "Trust and safety intelligence. Shows what senior T&S roles look like.", "watch": "Requires professional Latin American Spanish and senior trafficking/fraud investigation experience.", "lane_label": "Trust & safety / threat intel", "title": "Senior Analyst I - Trust & Safety", "org": "Flashpoint", "location": "United States", "remote_status": "Remote", "employment_type": "", "hours": "", "pay": "", "deadline": "", "summary": "Flashpoint seeks an analyst to support Trust & Safety work focused on violent extremism, organized crime, hate speech, and harmful or dangerous activity, particularly in Latin America and the Caribbean. The role involves researching and classifying content, developing and refining search queries, and producing analysis to inform moderation and policy decisions.", "duties": ["Build, test, and refine Boolean search strings and keyword queries to surface violative content across verticals, tracking performance against client accuracy targets.", "Review flagged content against platform policy definitions, applying nuanced judgment to edge cases such as satire and parody exclusions, coded language, and context-dependent violations.", "Produce concise written analysis and reporting on trends, emerging threats, and query performance for internal teams and client stakeholders.", "Quickly understand and act on evolving customer intelligence requirements and policy guidance.", "Write high-quality tactical and strategic assessments that inform moderation and policy decisions.", "Assess the credibility and relevance of raw content to determine appropriate classification.", "Maintain and contribute to internal knowledge bases and policy-interpretation references to keep the analyst team consistent.", "Nominate new collection sources and identify gaps in current query coverage.", "Distill complex findings into narratives for internal leadership and client stakeholders, and track the impact of query and policy changes over time.", "Work with the client's Trust & Safety team to build and refine search strategies, assess content against platform policy, and translate criminal and extremist activity into detection queries."], "required_qualifications": ["Native English plus full professional proficiency (C1/C2) in Latin American Spanish, written and spoken.", "Experience in online content moderation or trust and safety policy development.", "Experience investigating narcotics trafficking, human trafficking, or fraud networks.", "Familiarity with the operations of at least one of: Latin American organized crime and cartel networks, domestic or international extremist groups, or trafficking organizations.", "A working understanding of the intelligence cycle and how intelligence requirements translate into deliverables.", "Open source research skills, including social media navigation and online footprint investigation.", "Ability to rapidly break down complex topics and communicate risk clearly to technical and non-technical audiences while working autonomously in a remote environment.", "Experience as an analyst in a public- or private-sector intelligence role, on a social media content moderation or policy team, as a socio-geopolitical analyst, or as a Latin America and Caribbean regional analyst.", "Knowledge of the political, criminal, and extremist landscape across Mexico, Central America, South America, and the Caribbean, including cartel structures, FTO-designated groups, and regional gang dynamics.", "Understanding of real-world and online TTPs, underground slang, and operations of criminal and extremist groups, including counternarcotics, counter-human-trafficking, and violent criminal organization contexts.", "Ability to navigate, pivot, and use link analysis to surface threats and patterns across multiple social media platforms.", "Ability to analyze and distill complex policy frameworks to generate actionable intelligence and identify critical intelligence gaps.", "Ability to synthesize complex information into clear notes, structured spreadsheets, and concise written assessments, and capture action items and key decisions.", "Comfort operating in a fast-paced, product-driven environment, working semi-autonomously while following SOPs and operational security protocols.", "Ability to work independently and collaboratively in a fully remote setting and pick up new tools and workflows quickly."], "preferred_qualifications": ["Brazilian Portuguese is strongly preferred.", "Haitian Creole, French, Dutch, and Papiamento/u are highly desirable.", "Russian, Arabic, Mandarin, German, Hebrew, Persian, Turkish, or Hindi/Urdu are a plus."], "education_requirement": "", "how_to_apply": "Apply now via the job posting: https://jobs.greycroft.com/companies/flashpoint/jobs/88189953-senior-analyst-i-trust-safety", "archive": "", "urgent": "", "short": false, "loc": "remote", "paylabel": "Pay not listed", "saved": "saved/flashpoint.pdf"}, {"id": "recordedfuture", "url": "https://job-boards.greenhouse.io/recordedfuture/jobs/8917956002", "lane": "tns", "fit": "red", "paytype": "fulltime", "where": "Remote (Boston preferred)", "why": "Threat intelligence on Russian-speaking cybercrime: a long-term target.", "watch": "Requires Russian and 3+ years in cyber intelligence. Pay is $129-194K.", "lane_label": "Trust & safety / threat intel", "title": "Senior Threat Intelligence Analyst, Advanced Cybercrime and Engagements Team, Insikt Group", "org": "Recorded Future", "location": "Remote, USA; preference for Boston, MA or Washington, DC", "remote_status": "Remote", "employment_type": "Full-time", "hours": "", "pay": "Base salary range: $129,000–$193,500. The position may also be eligible for incentive compensation, equity, and benefits.", "deadline": "", "summary": "The Senior Threat Intelligence Analyst will research criminal activity on dark web and underground platforms, identify cybercrime trends and threat actors, and produce actionable intelligence for customers and internal stakeholders. The role involves proactive research, source development and maintenance, and collaboration across the Advanced Cybercrime and Engagements team and other Insikt Group teams.", "duties": ["Research, track, and author finished intelligence reports on cybercriminal threat actors, malicious tools and services, source types, Tactics, Techniques, and Procedures (TTPs), campaigns, and other cybercriminal-related topics.", "Identify, propose, and publish proactive Analyst Notes and reports on new and emerging threats, cybercriminal activities, and campaigns, specifically on dark web threat actors, money laundering operations, hacktivists, and threat groups associated with different types of cybercriminality for customer and public consumption.", "Drive sourcing, collecting, and curating new data into the Recorded Future Intelligence Cloud, using AI-assisted triage to cut through volume faster than manual review.", "Create and maintain access to underground sources and personas to achieve net-new intelligence.", "Contribute ideas for new automations or AI-assisted workflows to improve the speed and consistency of the team's production process, and share lessons learned/best practices broadly.", "Research and analyze criminal activity on dark web/underground platforms, such as forums, shops, marketplaces, and secure communication channels, to identify cybercrime trends and threat actors.", "Help identify sources, maintain persistence on those sources, and interact with threat actors to obtain information not publicly available.", "Conduct proactive research and respond to requests from Recorded Future colleagues and customers related to cybercriminal activities.", "Use open-source intelligence (OSINT), internal tools such as the Recorded Future Intelligence Operations Platform, and artificial intelligence (AI) to inform customers and internal stakeholders about the latest cybercriminal threat activities and trends, ensuring timely, actionable insights.", "Cross-collaborate with other Insikt Group teams on research projects and some customer requests."], "required_qualifications": ["Fluency or professional proficiency in Russian.", "Strong knowledge and experience with analytic tradecraft, the intelligence cycle, open-source intelligence gathering techniques, and strong intelligence writing skills, techniques, and methodologies.", "Be able to document and cogently explain to customers research findings.", "Be comfortable and confident in presenting research findings to customers and at conferences.", "3+ years of professional experience in roles in cyber intelligence, cybersecurity more broadly, cyber and cybercriminal investigations, or other related disciplines.", "Advanced knowledge of operational security (OPSEC) procedure and practices.", "Demonstrated experience operating on dark web sources (forums, marketplaces, and shops) and mediums of communication.", "Experience in engaging with cybercriminals and participating in covert operations in handling sensitive information.", "Knowledge of the structure and trends within the cybercriminal economy and landscape in different/specific regions: common communications vectors, source locations, operational security considerations, and more.", "Experience with handling, transacting in, and tracing cryptocurrencies.", "Knowledge of and ability to conduct blockchain and cryptocurrency investigations.", "Knowledge of money laundering, fraud, and current cybercrime TTPs.", "Ability to work collaboratively with others in a globally distributed environment.", "Regular, hands-on use of AI tools such as Claude or ChatGPT in your own research and writing, and the instinct to reach for them to speed up or automate a task.", "Ability to write clear, specific AI prompts and iterate as needed, and to fact-check and edit AI output for validity and objectivity."], "preferred_qualifications": ["BA/BS or MA/MS degree or equivalent experience in Computer Science, International Relations, Security Studies, Regional Studies, Criminology, or a related discipline.", "Knowledge and understanding of the cybercriminal ecosystem.", "Knowledge and understanding of the links and relationships between cybercriminal, hacktivist, extremist, and state-sponsored operations and organizations.", "Technical knowledge of malware trends, including ransomware, its functionality and capabilities, and how it’s impacting entities.", "Practical experience integrating or leveraging LLMs (for example, GPT, Claude, Gemini) in real-world applications, tools, or workflows to develop efficiencies in intelligence analysis."], "education_requirement": "Preferred: BA/BS or MA/MS degree, or equivalent experience, in Computer Science, International Relations, Security Studies, Regional Studies, Criminology, or a related discipline.", "how_to_apply": "Apply through the Recorded Future Greenhouse job page: https://job-boards.greenhouse.io/recordedfuture/jobs/8917956002. The application includes a required prompt asking candidates to describe their professional experience with cybercrime investigations and threat actor engagement in 4–7 sentences.", "archive": "", "urgent": "", "short": false, "loc": "remote", "paylabel": "$129-193.5K", "saved": "saved/recordedfuture.pdf"}, {"id": "isone", "url": "https://job-boards.greenhouse.io/isonewenglandinc/jobs/4462248009", "lane": "bridge", "fit": "red", "paytype": "fulltime", "where": "Holyoke MA, 3 days onsite", "why": "Regional energy-grid security analysis ($78-93K). Fits your energy interest.", "watch": "Requires a math or engineering degree and Python, with 3 days a week on site.", "lane_label": "Bridge roles (use your sales/logistics years)", "title": "Energy Security Analyst", "org": "ISO New England, Inc.", "location": "Holyoke, Massachusetts, United States", "remote_status": "Hybrid; 3 days per week onsite", "employment_type": "", "hours": "", "pay": "$78,000–$93,000 USD base salary, plus annual performance bonus", "deadline": "", "summary": "The Energy Security Analyst assesses regional energy reliability across operational and planning time horizons, using forecasts, scenarios, and sensitivity analyses to identify risks. The analyst oversees energy-emergency reporting and helps improve reliability products, communicate uncertainty, and support informed decisions by stakeholders and management.", "duties": ["Assess regional energy reliability across Operations and Operations Planning horizons, from near-real-time and seasonal analyses to outlooks extending 5–10 years.", "Use sophisticated tools maintained in partnership with the Energy Analytics team, IT support staff, and the research and development team to develop assumptions, forecasts, scenarios, and sensitivity analyses that identify and explain energy reliability risks facing New England.", "Gather initial-condition data from generators, weather and demand forecasters, outage coordinators, and pipeline operators, then develop a public report for stakeholders and a more detailed internal report to support management decisions.", "Strengthen existing energy reliability products and develop new approaches for assessing energy risk, advancing analysis from deterministic methods toward more rigorous, probabilistic assessments.", "Translate complex analyses into practical, reliable tools and communicate uncertainty clearly so stakeholders and management can review findings, provide input, and make informed decisions.", "Help define and communicate current and emerging power-system risks, enabling market developers to understand the challenges that proposed market solutions are intended to address."], "required_qualifications": ["Bachelor’s degree in actuarial science, mathematics, nuclear engineering, or another related field.", "Software-development experience, particularly with Python.", "Familiarity with risk quantification.", "Strong written, verbal, and presentation skills, including the ability to explain uncertainty and less-definitive analytical findings clearly.", "Ability to work in a small team and coordinate effectively with technical partners and data providers."], "preferred_qualifications": ["Experience with probabilistic methods is beneficial.", "Familiarity with bulk power-system operations or wholesale electricity markets is beneficial but not required."], "education_requirement": "Bachelor’s degree in actuarial science, mathematics, nuclear engineering, or another related field.", "how_to_apply": "Apply through the Greenhouse application page: https://job-boards.greenhouse.io/isonewenglandinc/jobs/4462248009", "archive": "", "urgent": "", "short": false, "loc": "hybrid", "paylabel": "$78-93K + bonus", "saved": "saved/isone.pdf"}, {"id": "tracelabs", "url": "https://www.tracelabs.org/get-involved", "lane": "volunteer", "fit": "green", "paytype": "volunteer", "where": "Online (Discord)", "why": "Crowdsourced OSINT to find missing persons. Builds hands-on OSINT credentials and contacts.", "watch": "Volunteer. Events (Search Party CTFs) happen on a set schedule.", "lane_label": "Volunteer & skill-building", "title": "OSINT volunteer (Search Party CTFs, community)", "org": "Trace Labs", "location": "", "remote_status": "Online participation through Discord; Search Party CTFs are held at information security conferences.", "employment_type": "Volunteer / community participation", "hours": "", "pay": "", "deadline": "", "summary": "Nonprofit that crowdsources open-source intelligence to help find missing persons. Members join via Discord and take part in Search Party capture-the-flag events at security conferences.", "duties": ["Participate in ongoing OSINT operations for real missing persons through the #ongoing-ops Discord channel.", "Collect evidence in the Trace Labs Trello Board and collaborate with other members working on an operation.", "Attend Search Party CTF events focused on open-source intelligence and missing persons."], "required_qualifications": [], "preferred_qualifications": [], "education_requirement": "", "how_to_apply": "Join the Trace Labs Discord community using the “Join Now” link on the page. The page also links to information about attending a Search Party CTF.", "archive": "https://web.archive.org/web/20261023091412/https://tracelabs.org/get-involved/", "urgent": "", "short": false, "loc": "remote", "paylabel": "Unpaid"}, {"id": "odnh", "url": "https://www.opendemocracynh.org/be_an_election_official", "lane": "volunteer", "fit": "green", "paytype": "volunteer", "where": "Your NH town", "why": "Local election roles such as ballot inspector or supervisor of the checklist. Gives you civic experience at the ground level of local government.", "watch": "In person on election days. Some roles pay a small stipend.", "lane_label": "Volunteer & skill-building", "title": "Local election official roles", "org": "Open Democracy NH", "location": "New Hampshire; in your local town or city", "remote_status": "In person at local polling places and municipal offices", "employment_type": "Elected or appointed local election and municipal positions; some are paid positions and some are described as community service roles", "hours": "Varies by role. Supervisors of the Checklist have a day-long commitment on Election Day and town meeting, plus occasional preparatory meetings during the year. Town and City Clerk positions may be part-time or full-time.", "pay": "Varies by role. Town and City Clerk positions are typically paid; Ballot Inspectors receive a small monetary stipend. Compensation for other roles is not specified.", "deadline": "", "summary": "Open Democracy describes local election and municipal roles through which community members can participate in the electoral process. Positions include Supervisors of the Checklist, clerks, moderators, selectmen, and Ballot Inspectors, with duties and terms varying by role and municipality.", "duties": ["Determine whether voter applicants are legally qualified to vote, update the checklist of registered voters, and maintain voter files (Supervisors of the Checklist).", "Attend periodic training sessions in Concord, hold mandatory supervisor sessions and post notices, and educate voters about changes to voting procedures or law (Supervisors of the Checklist).", "Before, during, and after elections, set up, register voters, facilitate party changes, enter data, and tally numbers required by the Secretary of State’s Office; after elections, enter new applications and status changes and scan checklists to record voter history (Supervisors of the Checklist).", "Preserve and manage vital records and other official city documents; conduct local, state, and federal elections; and prepare City Council agendas, minutes, and official notices (City Clerks).", "Keep town records, certify actions of Selectmen and other town officials, make official reports, collect fees, and carry out mandated laws and other municipal duties (Town Clerks).", "Ensure election officers are available and familiar with their duties, prepare the polling place, maintain order, and ensure required documentation is posted (Moderators). In towns, run the town meeting and explain meeting protocols.", "Help maintain the checklist and aid voters; sign warrants and election reports; help ensure proper counting and reporting of election results; maintain orderly voter flow; and appoint ballot inspectors if the major parties do not appoint them in time (Selectmen).", "Prepare polling-place documentation and reports, pick up ward supplies and documents, assist voters and the moderator, and, as directed, require Selectmen to sign and post election warrants (Ward Clerks).", "Serve in polling-place roles such as marking the checklist, handing out ballots, assisting voters at ballot booths, and receiving ballots at the ballot box (Ballot Inspectors/Ballot Clerks)."], "required_qualifications": ["Town Clerks must live in the town they serve.", "A Deputy Town Clerk must be a resident of the town and able to perform all the duties of the Town Clerk."], "preferred_qualifications": [], "education_requirement": "", "how_to_apply": "", "archive": "https://web.archive.org/web/20260712061614/https://www.opendemocracynh.org/be_an_election_official", "urgent": "", "short": false, "loc": "local", "paylabel": "Small stipend or paid, varies"}];